mapper.select:
SELECT ss.sector_id AS sectorId, s.category_raw AS categoryRaw, s.category_label AS categoryLabel, s.name AS sectorName, s.topic_id AS topicId, s.source AS sectorSource, ss.code, b.name AS stockName, b.market, b.total_market_cap AS totalMarketCap, b.float_market_cap AS floatMarketCap, ss.relation_level AS relationLevel, q.trade_date AS tradeDate, q.last_price AS lastPrice, q.pre_close AS preClose, q.open, q.high, q.low, q.change, q.change_pct AS changePct, q.volume_lots AS volumeLots, q.amount_wan AS amountWan, COALESCE(q.turnover_rate, t.latest_turnover_rate) AS turnoverRate, q.amplitude, q.total_market_cap_yi AS fundFlowTotalMarketCapYi, q.float_market_cap_yi AS fundFlowFloatMarketCapYi, t.total_shares AS totalShares, t.circulating_shares AS circulatingShares, q.captured_at AS capturedAt, COALESCE(ss.source, s.source) AS source FROM sec_stock_sector ss JOIN sec_sector s ON s.sector_id = ss.sector_id LEFT JOIN sec_stock_basic b ON b.code = ss.code LEFT JOIN LATERAL ( SELECT trade_date, last_price, pre_close, open, high, low, change, change_pct, volume_lots, amount_wan, turnover_rate, amplitude, total_market_cap_yi, float_market_cap_yi, captured_at FROM stock_fund_flow_snapshot WHERE deleted_at IS NULL AND code = ss.code ORDER BY trade_date DESC, captured_at DESC NULLS LAST LIMIT 1 ) q ON TRUE LEFT JOIN LATERAL ( SELECT latest_turnover_rate, circulating_shares, total_shares FROM stock_turnover_series_snapshot WHERE deleted_at IS NULL AND symbol = ss.code AND target_type = 'stock' AND period = '1d' AND adjust = 'qfq' ORDER BY latest_trade_date DESC NULLS LAST, generated_at DESC NULLS LAST LIMIT 1 ) t ON TRUE
ss.sector_id = #{sectorId}
AND s.category_raw = #{categoryRaw}
AND s.topic_id = #{topicId}
AND s.name = #{name}
ORDER BY ss.relation_level ASC NULLS LAST, ss.code ASC LIMIT #{limit}
